-- Idempotent starter process drafts. No publication, user provisioning or routing assignment.
-- Seed only when exactly one active global administrator can own the drafts.
WITH owner AS (SELECT MIN(id) id FROM users u WHERE u.organization_id='hmt' AND u.account_status='active' AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=u.id AND r.role IN ('super_admin','admin')) HAVING COUNT(*)=1) INSERT OR IGNORE INTO kb_articles(id,country_code,reference,title,category,service,state,data,author_id,last_editor_id) SELECT 'kb-starter-intake-'||c.code,c.code,'HMT-'||c.code||'-SD-001','Service Desk intake, classification and routing','Service Management','HMT Collabs','draft',json_set('{"summary": "Starter process guide for validating ticket intake and ownership. Review for HMT operational use before publication.", "symptoms": "A new ticket needs classification, service context and accountable ownership.", "prerequisites": "An authorized internal account; a customer organization; verified requester details; country routing and SLA policies reviewed by service management.", "procedure": "1. Open Service Desk and select Create Ticket. Confirm the customer, requester and contact.\n2. Record a clear title, observable symptoms, affected users and business impact. Select incident, service request, problem or change.\n3. Select impact and urgency using the documented operational impact. Confirm the derived priority.\n4. Capture service, category, site, environment, asset/serial, contract and SLA entitlement where known. Record evidence references without credentials or secrets.\n5. Leave owner blank only when an appropriate active routing rule exists or triage is required. Confirm the resulting owner and SLA targets after creation.\n6. Record the actual first response when a meaningful response has been provided. Assignment alone is not a response.\n7. Request independent fulfillment approval for controlled changes or approval-required requests before work starts.", "validation": "Confirm customer and country, priority, owner, captured SLA calendar, deadlines, context and intake event in the ticket timeline. Verify that unmatched tickets are visible for triage.", "rollback": "Correct intake context through the ticket record with an audit note. Escalate disputed priority or ownership to service management. Do not remove evidence or fabricate response timestamps.", "references": "HMT Collabs: Service Desk → Create Ticket; Routing & SLA Policies; Ticket Timeline.", "tags": "starter-draft,service-desk,process-guide", "review_date": ""}','$.review_date',date('now','+90 days')),o.id,o.id FROM countries c CROSS JOIN owner o WHERE c.code IN ('MU','MG','RW','BI');
WITH owner AS (SELECT MIN(id) id FROM users u WHERE u.organization_id='hmt' AND u.account_status='active' AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=u.id AND r.role IN ('super_admin','admin')) HAVING COUNT(*)=1) INSERT OR IGNORE INTO kb_articles(id,country_code,reference,title,category,service,state,data,author_id,last_editor_id) SELECT 'kb-starter-sla-'||c.code,c.code,'HMT-'||c.code||'-SD-002','SLA warning, breach and escalation triage','Service Management','HMT Collabs','draft',json_set('{"summary": "Starter process guide for investigating SLA exceptions. Default application targets require service-management review against actual customer commitments.", "symptoms": "A response or resolution warning/breach, an unassigned ticket or an overdue planned completion appears.", "prerequisites": "Access to the ticket and its captured SLA policy; an assigned engineer and a country escalation owner; customer commitments available for comparison.", "procedure": "1. Open Workflow & Escalations and the affected ticket. Identify whether the response clock, resolution clock or planned project end date is at risk.\n2. Check the captured policy and activation time. The default calendar is 24×7 elapsed time; planned task end and SLA resolution target are separate.\n3. Verify the owner and last work note. Contact the responsible engineer through the approved operational channel. Do not record a response until one has actually been given.\n4. For a warning, agree the next action and record an update. For a breach, notify the country escalation owner and document customer impact and recovery actions.\n5. Use on hold only with a meaningful reason. A hold pauses time only where the captured policy permits it. Resume before recording a first response when the clock is paused.\n6. Acknowledge the exception after review. Acknowledgement does not resolve the underlying condition or reset SLA targets.\n7. Validate recovery, record resolution evidence and follow the knowledge-backed closure process.", "validation": "Confirm the appropriate warning/breach and in-app notification exist, ownership is clear, response and resolution timestamps reflect actual actions, and alerts clear when their condition is resolved.", "rollback": "If a hold or status was entered incorrectly, correct it with an explanatory audit note. Escalate target disputes; do not reset deadlines to erase a breach. A reopened ticket retains original targets.", "references": "HMT Collabs: SLA Monitor; Workflow & Escalations; Service Desk operations & SLA performance report.", "tags": "starter-draft,service-desk,process-guide", "review_date": ""}','$.review_date',date('now','+90 days')),o.id,o.id FROM countries c CROSS JOIN owner o WHERE c.code IN ('MU','MG','RW','BI');
WITH owner AS (SELECT MIN(id) id FROM users u WHERE u.organization_id='hmt' AND u.account_status='active' AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=u.id AND r.role IN ('super_admin','admin')) HAVING COUNT(*)=1) INSERT OR IGNORE INTO kb_articles(id,country_code,reference,title,category,service,state,data,author_id,last_editor_id) SELECT 'kb-starter-project-'||c.code,c.code,'HMT-'||c.code||'-SD-003','Project task and Service Desk ticket execution','Service Management','HMT Collabs','draft',json_set('{"summary": "Starter process guide for operating the linked task/ticket lifecycle. It covers workflow handling and does not replace a technical implementation runbook.", "symptoms": "A project task needs a linked ticket, execution status is blocked, or ticket completion needs to update project delivery.", "prerequisites": "An accessible project; assigned task owner; valid task start/end dates; accepted commercial delivery handovers where applicable; approved implementation evidence and predecessor tasks.", "procedure": "1. In Project Management, open WBS, tasks & dependencies. Confirm the task title, scope, owner, start date, end date and predecessors.\n2. Confirm required commercial handovers have been accepted. The system creates one linked ticket for an eligible unfinished task; scheduled reconciliation retries eligible tasks.\n3. Open the linked Service Desk ticket and verify owner, planned dates and captured SLA targets. Later planning changes do not silently reset SLA targets.\n4. Start execution from the ticket after the current planned start and required predecessors. Record actual first response and work notes.\n5. Execute the separately approved technical runbook. Document results, validation and any deviation under the project change process.\n6. Resolve the ticket after successful validation. Select the actual current published knowledge material used and explain how it was used before closure.\n7. Close the ticket and confirm the linked project task is done. Project stage approval and project closure remain independent decisions.", "validation": "Confirm one ticket per task, correct owner, task/ticket status consistency, knowledge version and usage evidence, project revision and audit entries. A reopened closed ticket should reopen its task.", "rollback": "Stop delivery if the project/task is held or cancelled or dependencies are incomplete. Escalate to the project manager. Reopen with a supervisor reason when further work is required; never manually mark a linked task done to bypass ticket closure.", "references": "HMT Collabs: Project Management → WBS, tasks & dependencies; Service Desk → Manage Ticket; Project task tickets & delivery report.", "tags": "starter-draft,service-desk,process-guide", "review_date": ""}','$.review_date',date('now','+90 days')),o.id,o.id FROM countries c CROSS JOIN owner o WHERE c.code IN ('MU','MG','RW','BI');
WITH owner AS (SELECT MIN(id) id FROM users u WHERE u.organization_id='hmt' AND u.account_status='active' AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=u.id AND r.role IN ('super_admin','admin')) HAVING COUNT(*)=1) INSERT OR IGNORE INTO kb_articles(id,country_code,reference,title,category,service,state,data,author_id,last_editor_id) SELECT 'kb-starter-knowledge-'||c.code,c.code,'HMT-'||c.code||'-SD-004','Knowledge authoring, independent review and ticket citation','Service Management','HMT Collabs','draft',json_set('{"summary": "Starter process guide for knowledge governance. Publication must be independently reviewed; this process article is not a substitute for the technical material used to resolve an incident.", "symptoms": "A ticket has no suitable published article, a procedure needs revision, or a cited article is retired or overdue for review.", "prerequisites": "An internal author, a separate eligible leadership reviewer, validated operational evidence, a substantive procedure and a future review date.", "procedure": "1. Search Knowledge Base for relevant published material and confirm service, country, symptoms and applicability.\n2. If no suitable material exists, create a draft with a unique reference, summary, prerequisites, procedure, validation, rollback, references, tags and review date. Remove credentials, customer secrets and unsupported claims.\n3. Submit to an eligible independent reviewer. The author and last draft editor cannot approve their own work.\n4. The reviewer validates accuracy, safety, evidence and applicability. Reject incomplete material or publish an approved version with a substantive review note.\n5. In ticket closure, select the current published version within its review date. Explain the actual steps used and the resulting validation. Cite the technical runbook for technical remediation rather than this governance guide alone.\n6. Revise published material through a new draft and independent publication. Earlier published versions remain preserved as historical evidence.\n7. Retire obsolete material with a governance reason. Retired or expired-review material cannot support new closures, while exact previously cited versions remain visible in ticket evidence.", "validation": "Verify independent reviewer, published version, review date, ticket citation and usage note. Check knowledge publication/usage audit and review-health reports. A draft or unreviewed starter must not be selectable for closure.", "rollback": "Reject an unsafe or incomplete draft. Retire an unsuitable published article through country governance and prepare a corrected draft. Preserve historical versions and audit evidence; do not silently overwrite a published procedure.", "references": "HMT Collabs: Knowledge Base; Knowledge Reviews; Knowledge publication & usage audit report.", "tags": "starter-draft,service-desk,process-guide", "review_date": ""}','$.review_date',date('now','+90 days')),o.id,o.id FROM countries c CROSS JOIN owner o WHERE c.code IN ('MU','MG','RW','BI');
INSERT INTO sd_events(id,article_id,country_code,action,snapshot) SELECT lower(hex(randomblob(16))),a.id,a.country_code,'Starter knowledge draft prepared',json_object('reference',a.reference,'prepared_by','Assistant on user instruction','state','draft','publication','Independent review required') FROM kb_articles a WHERE a.id LIKE 'kb-starter-%' AND NOT EXISTS(SELECT 1 FROM sd_events e WHERE e.article_id=a.id AND e.action='Starter knowledge draft prepared');
